mapper.select:
SELECT /*selectMasterMpDscropProtectList*/ Y.USE_TEXT, Y.BUYER_ITEM_NO, Y.MM_DATE, Y.EE_DATE, Y.DESCRIPTION, Y.SPECIFICATION, Y.MAKER_NAME, Y.MM_STATUS, Y.DD_RECV_STATUS, Y.DD_ED_STATUS, Y.EE_RECV_STATUS, Y.EE_ED_STATUS, Y.ES_MK_STATUS, Y.ES_PD_STATUS, Y.ES_QA_STATUS, Y.GUBUN, Y.RD_DATE, Y.DD_DATE, Y.ES_DATE, Y.PLANT, Y.BYCA_COMORG_CODE, Y.BUYER, Y.OPKG_SEQ, Y.CONTRACT_NO, Y.CONTRACT_SEQ, Y.RECV_FLAG, Y.USE_FLAG, Y.GUBUN_FLAG, Y.ES_STATUS, Y.SAFETY_OPEN_FLAG, Y.ES_FI_STATUS, Y.MM_STATUS_YN, Y.MM_WORK_DATE, Y.MM_REMARK, Y.DD_STATUS_YN, Y.DD_WORK_DATE, Y.DD_REMARK, Y.EE_STATUS_YN, Y.EE_WORK_DATE, Y.EE_REMARK, Y.ES_MK_STATUS_YN, Y.ES_MK_WORK_DATE, Y.ES_MK1_REMARK, Y.ES_PD1_STATUS_YN, Y.ES_PD_WORK_DATE, Y.ES_PD1_REMARK, Y.ES_QA1_STATUS_YN, Y.ES_QA_WORK_DATE, Y.ES_QA1_REMARK, Y.ES_FI_STATUS_YN, Y.ES_FI_WORK_DATE, Y.ES_FI_REMARK, Y.AGENT_SELECT, Y.BUYER_REQ, Y.CHANGE_DATE, Y.CHANGE_USER, Y.RETURN_CNT, Y.RETURN_TEAM_CNT FROM ( SELECT ROWNUM NUM, X.USE_TEXT, X.BUYER_ITEM_NO, X.MM_DATE, X.EE_DATE, X.DESCRIPTION, X.SPECIFICATION, X.MAKER_NAME, X.MM_STATUS, X.DD_RECV_STATUS, X.DD_ED_STATUS, X.EE_RECV_STATUS, X.EE_ED_STATUS, X.ES_MK_STATUS, X.ES_PD_STATUS, X.ES_QA_STATUS, X.GUBUN, X.RD_DATE, X.DD_DATE, X.ES_DATE, X.PLANT, X.BYCA_COMORG_CODE, X.BUYER, X.OPKG_SEQ, X.CONTRACT_NO, X.CONTRACT_SEQ, X.RECV_FLAG, X.USE_FLAG, X.GUBUN_FLAG, X.ES_STATUS, X.SAFETY_OPEN_FLAG, X.ES_FI_STATUS, X.MM_STATUS_YN, X.MM_WORK_DATE, X.MM_REMARK, X.DD_STATUS_YN, X.DD_WORK_DATE, X.DD_REMARK, X.EE_STATUS_YN, X.EE_WORK_DATE, X.EE_REMARK, X.ES_MK_STATUS_YN, X.ES_MK_WORK_DATE, X.ES_MK1_REMARK, X.ES_PD1_STATUS_YN, X.ES_PD_WORK_DATE, X.ES_PD1_REMARK, X.ES_QA1_STATUS_YN, X.ES_QA_WORK_DATE, X.ES_QA1_REMARK, X.ES_FI_STATUS_YN, X.ES_FI_WORK_DATE, X.ES_FI_REMARK, X.AGENT_SELECT, X.BUYER_REQ, X.CHANGE_DATE, X.CHANGE_USER, X.RETURN_CNT, X.RETURN_TEAM_CNT FROM ( SELECT CASE WHEN A.USE_FLAG = 'S' AND A.RECV_FLAG NOT IN ('ED','FY') THEN '1' ELSE CASE WHEN A.USE_FLAG = 'N' AND A.RECV_FLAG NOT IN ('ED','FY') THEN '2' ELSE CASE WHEN A.USE_FLAG = 'S' AND A.RECV_FLAG IN ('ED','FY') THEN '3' ELSE CASE WHEN A.USE_FLAG = 'N' AND A.RECV_FLAG IN ('ED','FY') THEN '4' END END END END AS SO_FLAG, DECODE(A.USE_FLAG,'S','긴급','N','일반','') AS USE_TEXT, A.BUYER_ITEM_NO AS BUYER_ITEM_NO, NVL(A.MM_DATE,TO_CHAR(SYSDATE,'YYYYMMDD')) AS MM_DATE, NVL(A.EE_DATE,TO_CHAR(SYSDATE,'YYYYMMDD')) AS EE_DATE, A.DESCRIPTION AS DESCRIPTION, A.SPECIFICATION AS SPECIFICATION, A.MAKER_NAME AS MAKER_NAME,
DECODE(A.RECV_FLAG,'ED','3', 'FY','4', 'GB','6', DECODE(NVL(A.MM_STATUS,'N'),'N','5','ED','2')) AS MM_STATUS, DECODE(A.RECV_FLAG,'ED','3', 'FY','4', 'GB','6', DECODE(NVL(A.DD_STATUS,'N'),'RC','2','ED','2','5')) AS DD_RECV_STATUS, DECODE(A.RECV_FLAG,'ED','3', 'FY','4', 'GB','6', DECODE(NVL(A.DD_STATUS,'N'),'ED','2','5')) AS DD_ED_STATUS, DECODE(A.RECV_FLAG,'ED','3', 'FY','4', 'GB','6', DECODE(NVL(A.EE_STATUS,'N'),'RC','2','ED','2','5')) AS EE_RECV_STATUS, DECODE(A.RECV_FLAG,'ED','3', 'FY','4', 'GB','6', DECODE(NVL(A.EE_STATUS,'N'),'ED','2','5')) AS EE_ED_STATUS, DECODE(A.RECV_FLAG,'ED','3', 'FY','4', 'GB','6', DECODE(NVL(A.ES_MK1_STATUS,'N'),'N','5','B','6','Y','2','5')) AS ES_MK_STATUS,
DECODE(A.RECV_FLAG,'ED','3', 'FY','4', 'GB','6', DECODE(NVL(A.ES_PD1_STATUS,'N'),'N','5','B','6','Y','2','5')) AS ES_PD_STATUS,
DECODE(A.RECV_FLAG,'ED','3', 'FY','4', 'GB','6', DECODE(NVL(A.ES_QA1_STATUS,'N'),'N','5','B','6','Y','2','5')) AS ES_QA_STATUS, DECODE(NVL(A.SAFETY_OPEN_FLAG,'N'), 'Y','7','8') AS SAFETY_OPEN_FLAG, DECODE(A.RECV_FLAG,'ED','/resources/images/icon_y.gif', 'FY','4', 'GB','6', DECODE(NVL(A.ES_FI_STATUS,'N'),'N','5','B','6','Y','/resources/images/icon_r.gif','5')) AS ES_FI_STATUS,
DECODE(A.RECV_FLAG,'ED','/resources/images/icon_y.gif', 'FY','/resources/images/icon_g.gif', 'GB','/resources/images/icon_b.gif', DECODE(NVL(A.MM_STATUS,'N'),'N','/resources/images/icon_w.gif','ED','/resources/images/icon_r.gif')) AS MM_STATUS, DECODE(A.RECV_FLAG,'ED','/resources/images/icon_y.gif', 'FY','/resources/images/icon_g.gif', 'GB','/resources/images/icon_b.gif', DECODE(NVL(A.DD_STATUS,'N'),'RC','/resources/images/icon_r.gif','ED','/resources/images/icon_r.gif','/resources/images/icon_w.gif')) AS DD_RECV_STATUS, DECODE(A.RECV_FLAG,'ED','/resources/images/icon_y.gif', 'FY','/resources/images/icon_g.gif', 'GB','/resources/images/icon_b.gif', DECODE(NVL(A.DD_STATUS,'N'),'ED','/resources/images/icon_r.gif','/resources/images/icon_w.gif')) AS DD_ED_STATUS, DECODE(A.RECV_FLAG,'ED','/resources/images/icon_y.gif', 'FY','/resources/images/icon_g.gif', 'GB','/resources/images/icon_b.gif', DECODE(NVL(A.EE_STATUS,'N'),'RC','/resources/images/icon_r.gif','ED','/resources/images/icon_r.gif','/resources/images/icon_w.gif')) AS EE_RECV_STATUS, DECODE(A.RECV_FLAG,'ED','/resources/images/icon_y.gif', 'FY','/resources/images/icon_g.gif', 'GB','/resources/images/icon_b.gif', DECODE(NVL(A.EE_STATUS,'N'),'ED','/resources/images/icon_r.gif','/resources/images/icon_w.gif')) AS EE_ED_STATUS, DECODE(A.RECV_FLAG,'ED','/resources/images/icon_y.gif', 'FY','/resources/images/icon_g.gif', 'GB','/resources/images/icon_b.gif', DECODE(NVL(A.ES_MK1_STATUS,'N'),'N','/resources/images/icon_w.gif','B','/resources/images/icon_b.gif','Y','/resources/images/icon_r.gif','/resources/images/icon_w.gif')) AS ES_MK_STATUS,
DECODE(A.RECV_FLAG,'ED','/resources/images/icon_y.gif', 'FY','/resources/images/icon_g.gif', 'GB','/resources/images/icon_b.gif', DECODE(NVL(A.ES_PD1_STATUS,'N'),'N','/resources/images/icon_w.gif','B','/resources/images/icon_b.gif','Y','/resources/images/icon_r.gif','/resources/images/icon_w.gif')) AS ES_PD_STATUS,
DECODE(A.RECV_FLAG,'ED','/resources/images/icon_y.gif', 'FY','/resources/images/icon_g.gif', 'GB','/resources/images/icon_b.gif', DECODE(NVL(A.ES_QA1_STATUS,'N'),'N','/resources/images/icon_w.gif','B','/resources/images/icon_b.gif','Y','/resources/images/icon_r.gif','/resources/images/icon_w.gif')) AS ES_QA_STATUS, DECODE(NVL(A.SAFETY_OPEN_FLAG,'N'), 'Y','/resources/images/icon_bl.gif','/resources/images/icon_x.gif') AS SAFETY_OPEN_FLAG, DECODE(A.RECV_FLAG,'ED','/resources/images/icon_y.gif', 'FY','/resources/images/icon_g.gif', 'GB','/resources/images/icon_b.gif', DECODE(NVL(A.ES_FI_STATUS,'N'),'N','/resources/images/icon_w.gif','B','/resources/images/icon_b.gif','Y','/resources/images/icon_r.gif','/resources/images/icon_w.gif')) AS ES_FI_STATUS,
DECODE(A.GUBUN_FLAG,'NW','신규','OD','기존','ERR') AS GUBUN, NVL(A.RD_DATE,TO_CHAR(SYSDATE,'YYYYMMDD')) AS RD_DATE, NVL(A.DD_DATE,TO_CHAR(SYSDATE,'YYYYMMDD')) AS DD_DATE, NVL(A.ES_DATE,TO_CHAR(SYSDATE,'YYYYMMDD')) AS ES_DATE,
A.PLANT AS PLANT, A.BYCA_COMORG_CODE AS BYCA_COMORG_CODE, A.BUYER AS BUYER, A.OPKG_SEQ AS OPKG_SEQ, A.CONTRACT_NO AS CONTRACT_NO, A.CONTRACT_SEQ AS CONTRACT_SEQ, A.RECV_FLAG AS RECV_FLAG, A.USE_FLAG AS USE_FLAG, A.GUBUN_FLAG AS GUBUN_FLAG, DECODE(NVL(A.ES_MK1_STATUS,'N'),'Y', DECODE(NVL(A.ES_PD1_STATUS,'N'),'Y', DECODE(NVL(A.ES_QA1_STATUS,'N'),'Y','ED','RC'),'RC'),'RC') AS ES_STATUS,
DECODE(NVL(A.MM_STATUS,'N'),'N','미완료','ED','완료') AS MM_STATUS_YN, TO_CHAR(A.MM_WORK_DATE,'YYYYMMDD')||' '|| DECODE(NVL(TRIM(A.MM_WORK_DATE),''),'','', SUBSTR(TO_CHAR(A.MM_WORK_DATE,'HH24MISS'),1,2)||':'||SUBSTR(TO_CHAR(A.MM_WORK_DATE,'HH24MISS'),3,2)) AS MM_WORK_DATE, replace(A.MM_REMARK, chr(13)||CHR(10), ' ') AS MM_REMARK, DECODE(NVL(A.DD_STATUS,'N'),'N','미처리','RC','접수','ED','완료') AS DD_STATUS_YN, TO_CHAR(A.DD_WORK_DATE,'YYYYMMDD')||' '|| DECODE(NVL(TRIM(A.DD_WORK_DATE),''),'','', SUBSTR(TO_CHAR(A.DD_WORK_DATE,'HH24MISS'),1,2)||':'||SUBSTR(TO_CHAR(A.DD_WORK_DATE,'HH24MISS'),3,2)) AS DD_WORK_DATE, replace(A.DD_REMARK, chr(13)||CHR(10), ' ') AS DD_REMARK, DECODE(NVL(A.EE_STATUS,'N'),'N','미처리','RC','접수','ED','완료') AS EE_STATUS_YN, TO_CHAR(A.EE_WORK_DATE,'YYYYMMDD')||' '|| DECODE(NVL(TRIM(A.EE_WORK_DATE),''),'','', SUBSTR(TO_CHAR(A.EE_WORK_DATE,'HH24MISS'),1,2)||':'||SUBSTR(TO_CHAR(A.EE_WORK_DATE,'HH24MISS'),3,2)) AS EE_WORK_DATE, replace(A.EE_REMARK, chr(13)||CHR(10), ' ') AS EE_REMARK, DECODE(NVL(A.ES_MK_STATUS,A.ES_MK1_STATUS),'N','미확인','Y','확인','B','반려') AS ES_MK_STATUS_YN, TO_CHAR(A.ES_MK_WORK_DATE,'YYYYMMDD')||' '|| DECODE(NVL(TRIM(A.ES_MK_WORK_DATE),''),'','', SUBSTR(TO_CHAR(A.ES_MK_WORK_DATE,'HH24MISS'),1,2)||':'||SUBSTR(TO_CHAR(A.ES_MK_WORK_DATE,'HH24MISS'),3,2)) AS ES_MK_WORK_DATE, replace(A.ES_MK1_REMARK, chr(13)||CHR(10), ' ') AS ES_MK1_REMARK, DECODE(NVL(A.ES_PD_STATUS,A.ES_PD1_STATUS),'N','미확인','Y','확인','B','반려') AS ES_PD1_STATUS_YN, TO_CHAR(A.ES_PD_WORK_DATE,'YYYYMMDD')||' '|| DECODE(NVL(TRIM(A.ES_PD_WORK_DATE),''),'','', SUBSTR(TO_CHAR(A.ES_PD_WORK_DATE,'HH24MISS'),1,2)||':'||SUBSTR(TO_CHAR(A.ES_PD_WORK_DATE,'HH24MISS'),3,2)) AS ES_PD_WORK_DATE, replace(A.ES_PD1_REMARK, chr(13)||CHR(10), ' ') AS ES_PD1_REMARK, DECODE(NVL(A.ES_QA_STATUS,A.ES_QA1_STATUS),'N','미확인','Y','확인','B','반려') AS ES_QA1_STATUS_YN, TO_CHAR(A.ES_QA_WORK_DATE,'YYYYMMDD')||' '|| DECODE(NVL(TRIM(A.ES_QA_WORK_DATE),''),'','', SUBSTR(TO_CHAR(A.ES_QA_WORK_DATE,'HH24MISS'),1,2)||':'||SUBSTR(TO_CHAR(A.ES_QA_WORK_DATE,'HH24MISS'),3,2)) AS ES_QA_WORK_DATE, replace(A.ES_QA1_REMARK, chr(13)||CHR(10), ' ') AS ES_QA1_REMARK, DECODE(A.ES_FI_STATUS,'N','미확인','Y','확인','B','반려') AS ES_FI_STATUS_YN, TO_CHAR(A.ES_FI_WORK_DATE,'YYYYMMDD')||' '|| DECODE(NVL(TRIM(A.ES_FI_WORK_DATE),''),'','', SUBSTR(TO_CHAR(A.ES_FI_WORK_DATE,'HH24MISS'),1,2)||':'||SUBSTR(TO_CHAR(A.ES_FI_WORK_DATE,'HH24MISS'),3,2)) AS ES_FI_WORK_DATE, replace(A.ES_FI_REMARK, chr(13)||CHR(10), ' ') AS ES_FI_REMARK, DECODE(NVL(TRIM(A.AGENT),''),'','', (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.AGENT)) AS AGENT_SELECT, DECODE(NVL(TRIM(A.BUYER),''),'','', (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.BUYER)) AS BUYER_REQ, A.CHANGE_DATE AS CHANGE_DATE, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.CHANGE_USER_ID) AS CHANGE_USER, (SELECT COUNT(*) FROM DONGOPKG_HISTORY WHERE PLANT = A.PLANT AND BYCA_COMORG_CODE = A.BYCA_COMORG_CODE AND BUYER = A.BUYER AND OPKG_SEQ = A.OPKG_SEQ AND RD_DATE = A.RD_DATE AND BUYER_ITEM_NO = A.BUYER_ITEM_NO) AS RETURN_CNT, (SELECT '( 마케팅팀 : '|| NVL(sum(decode(RETURN_USER_DEPT,'MK',1,0)),0) || ','|| ' 상품개발팀 : '|| NVL(sum(decode(RETURN_USER_DEPT,'PD',1,0)),0) || ','|| ' 품질보증팀 : '|| NVL(sum(decode(RETURN_USER_DEPT,'QA',1,0)),0) || ','|| ' 최종확인 : '|| NVL(sum(decode(RETURN_USER_DEPT,'FI',1,0)),0) || ' )' FROM DONGOPKG_HISTORY WHERE PLANT = A.PLANT AND BYCA_COMORG_CODE = A.BYCA_COMORG_CODE AND BUYER = A.BUYER AND OPKG_SEQ = A.OPKG_SEQ AND RD_DATE = A.RD_DATE AND BUYER_ITEM_NO = A.BUYER_ITEM_NO)AS RETURN_TEAM_CNT
FROM DONGOPKG A WHERE A.STATUS <> 'D' AND A.BYCA_COMORG_CODE IN ('KRDONGG004')
AND A.RD_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND A.MM_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND A.DD_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND A.EE_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND A.ES_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND A.RECV_FLAG = #{st_recv_flag}
AND A.DD_STATUS = #{st_dd_status}
AND A.EE_STATUS = #{st_ee_status}
AND NVL(A.ES_FI_STATUS,'N') = #{st_fi_status}
AND A.PRODUCT_FLAG = #{st_product_flag}
AND (A.DESCRIPTION LIKE '%' || #{st_desc_spec} || '%' OR A.SPECIFICATION LIKE '%' || #{st_desc_spec} || '%' OR A.DESCRIPTION LIKE UPPER( '%' || #{st_desc_spec} || '%') OR A.SPECIFICATION LIKE UPPER( '%' || #{st_desc_spec} || '%') OR A.DESCRIPTION LIKE LOWER( '%' || #{st_desc_spec} || '%') OR A.SPECIFICATION LIKE LOWER( '%' || #{st_desc_spec} || '%') )
AND A.BUYER = #{st_buyer}
AND A.BUYER_ITEM_NO LIKE '%' || #{st_buyer_item_no} || '%'
ORDER BY SO_FLAG, A.USE_FLAG DESC, A.RD_DATE DESC --시작일
ORDER BY SO_FLAG, A.USE_FLAG DESC, A.MM_DATE DESC --마케팅완료일
ORDER BY SO_FLAG, A.USE_FLAG DESC, A.DD_DATE DESC --문안완료일
ORDER BY SO_FLAG, A.USE_FLAG DESC, A.EE_DATE DESC --디자인완료일
ORDER BY SO_FLAG, A.USE_FLAG DESC, A.ES_DATE DESC --최종확정일
) X ) Y
